<?php
declare(strict_types=1);
require_once __DIR__.'/PaymentSettings.php';
require_once __DIR__.'/CheckoutLinks.php';
final class RidePayments
{
    public function __construct(private PDO $db,private array $env=[]){}
    private function query(string $sql,array $args=[]):PDOStatement{$q=$this->db->prepare($sql);$q->execute($args);return $q;}
    public function available():bool{$c=(new PaymentSettings($this->db,$this->env))->config();$raw=$this->query("SELECT data FROM jingo_settings WHERE id='transport-plan'")->fetchColumn();$p=$raw?json_decode($raw,true,512,JSON_THROW_ON_ERROR):[];return !empty($p['qrEnabled'])&&$c['mode']==='LIVE'&&SepaySettings::ready($c);}
    public static function eligible(array $r,array $d,bool $admin=false):bool{return ($d['channel']??'WEB')==='WEB'&&($d['paymentStatus']??'UNPAID')==='UNPAID'&&is_int($d['total']??null)&&$d['total']>0&&$d['total']<=15000000000&&(in_array($r['status'],['MATCHED','WAITING_PICKUP','PICKED_UP','RUNNING','COMPLETED'],true)||!$admin&&$r['status']==='PENDING'&&empty($d['autoPool'])&&($d['mode']??'PRIVATE')==='PRIVATE');}
    public function locked(string $code,bool $admin=true):array
    {
        if(!$this->db->inTransaction())throw new LogicException('Ride payment requires transaction.');$r=$this->query('SELECT * FROM jingo_ride_bookings WHERE code=? FOR UPDATE',[$code])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new HttpError(404,'Không tìm thấy đơn xe.');$d=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);CheckoutLinks::guard($this->db,'rideId',$r['id']);if(!self::eligible($r,$d,$admin))throw new HttpError(409,'Đơn xe đã thu/hủy, chưa xác nhận/chốt nhóm, thuộc POS hoặc số tiền không hợp lệ.');return ['row'=>$r,'data'=>$d,'total'=>$d['total']];
    }
    public function checkout(array $in,?string $actor=null):array
    {
        $keys=$actor===null?['code','requestKey']:['id'];if(array_diff(array_keys($in),$keys)||count($in)!==count($keys)||$actor===null&&(!is_string($in['code']??null)||!preg_match('/^JM-X[A-F0-9]{12}$/D',$in['code'])||!is_string($in['requestKey']??null)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$in['requestKey']))||$actor!==null&&(!is_string($in['id']??null)||!preg_match('/^[a-f0-9-]{36}$/D',$in['id'])))throw new HttpError(400,'Kiểm tra mã xe và khóa tra cứu.');
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');if(!$this->available())throw new HttpError(400,'QR xe chưa bật hoặc SePay chưa sẵn sàng LIVE.');$settings=new PaymentSettings($this->db,$this->env);if(!str_starts_with($settings->base(),'https://'))throw new HttpError(503,'QR LIVE cần HTTPS.');$r=$actor===null?$this->query('SELECT * FROM jingo_ride_bookings WHERE code=? FOR UPDATE',[$in['code']])->fetch(PDO::FETCH_ASSOC):$this->query('SELECT * FROM jingo_ride_bookings WHERE id=? FOR UPDATE',[$in['id']])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new HttpError(404,'Không tìm thấy đơn xe.');$d=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);if($actor===null&&(!hash_equals($r['request_key'],strtolower($in['requestKey']))||($d['channel']??'WEB')==='POS'))throw new HttpError(404,'Không tìm thấy đơn xe.');$s=$this->locked($r['code'],$actor!==null);$c=$settings->config();$snapshot=['bankCode'=>$c['bankCode'],'accountNumber'=>$c['accountNumber'],'accountName'=>$c['accountName']];$q=$this->query("SELECT * FROM jingo_ride_payment_attempts WHERE ride_id=? AND status='PENDING' AND expires_at>UTC_TIMESTAMP(6) AND amount=? AND config_version=? ORDER BY created_at DESC,id DESC",[$r['id'],$s['total'],$c['version']]);$a=null;while($row=$q->fetch(PDO::FETCH_ASSOC))if(json_decode($row['config'],true,512,JSON_THROW_ON_ERROR)===$snapshot){$a=$row;break;}
            if(!$a){$id='JMR'.strtoupper(bin2hex(random_bytes(12)));$this->query('INSERT INTO jingo_ride_payment_attempts(id,ride_id,amount,config_version,config,expires_at) VALUES (?,?,?,?,?,DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 15 MINUTE))',[$id,$r['id'],$s['total'],$c['version'],json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);$a=$this->query('SELECT * FROM jingo_ride_payment_attempts WHERE id=?',[$id])->fetch(PDO::FETCH_ASSOC);if($actor!==null)$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'ride.qr.create',$r['id']]);}$this->db->commit();return ['code'=>$r['code'],'memo'=>$a['id'],'amount'=>$s['total'],'expiresAt'=>$a['expires_at']]+$snapshot+['qrUrl'=>'https://vietqr.app/img?'.http_build_query(['acc'=>$snapshot['accountNumber'],'bank'=>$snapshot['bankCode'],'amount'=>(string)$s['total'],'des'=>$a['id']],'','&',PHP_QUERY_RFC3986)];
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function credit(array $s,string $reference,string $actor='gateway:SEPAY'):void
    {
        if(!$this->db->inTransaction()||!preg_match('/^SEPAY:LIVE:[0-9]{1,30}$/D',$reference)||$actor==='')throw new LogicException('Invalid ride credit context.');$r=$s['row'];$d=$s['data'];$this->query("INSERT INTO jingo_payment_references(reference_hash,reference,kind,entity_id,amount) VALUES (?,?,'RIDE_PAYMENT',?,?)",[hash('sha256',$reference),$reference,$r['id'],$s['total']]);$d=array_replace($d,['paymentStatus'=>'PAID','paidAmount'=>$s['total'],'paidAt'=>gmdate('Y-m-d\TH:i:s\Z'),'paymentReference'=>$reference]);$this->query('UPDATE jingo_ride_bookings SET data=?,version=version+1 WHERE id=?',[json_encode($d,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$r['id']]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'ride.pay',$r['id']]);
    }
    public function settle(?string $token,string $external,int $amount,string $fingerprint,string $reason,array $initial,array $current,string $credential):array
    {
        if(!$this->db->inTransaction())throw new LogicException('Ride settlement requires the authenticated webhook transaction.');if($initial['mode']!=='LIVE')throw new HttpError(400,'Đơn xe chỉ nhận QR LIVE.');$id='SEPAY:LIVE:'.$external;$a=$token?$this->query('SELECT * FROM jingo_ride_payment_attempts WHERE id=?',[$token])->fetch(PDO::FETCH_ASSOC):false;$r=$a?$this->query('SELECT * FROM jingo_ride_bookings WHERE id=? FOR UPDATE',[$a['ride_id']])->fetch(PDO::FETCH_ASSOC):false;$s=null;if(!$a||!$r)$reason=$reason?:'Không tìm thấy yêu cầu thanh toán xe.';
        if($a){$snapshot=json_decode($a['config'],true,512,JSON_THROW_ON_ERROR);if($a['status']!=='PENDING'||strtotime($a['expires_at'].' UTC')<=time())$reason='QR đã hết hạn hoặc đã dùng.';if($snapshot['bankCode']!==$current['bankCode']||$snapshot['accountNumber']!==$current['accountNumber'])$reason='Tài khoản nhận đã thay đổi.';if((int)$a['amount']!==$amount)$reason='Số tiền không khớp đơn xe.';}
        if($r)try{$s=$this->locked($r['code'],false);if($s['total']!==$amount)$reason='Số tiền không khớp đơn xe.';}catch(HttpError $e){$reason=$reason?:$e->getMessage();}
        if($current['mode']!=='LIVE'||!$current['sepayEnabled']||SepaySettings::credential($current)!==$credential)$reason='Cổng hoặc khóa SePay đã thay đổi.';if($this->query('SELECT reference_hash FROM jingo_payment_references WHERE reference_hash=?',[hash('sha256',$id)])->fetchColumn())$reason='Giao dịch đã ghi thu.';$status=$reason!==''?'REVIEW':'PAID';$this->query("INSERT INTO jingo_gateway_events(id,provider,mode,amount,status,reason,fingerprint) VALUES (?,'SEPAY','LIVE',?,?,?,?)",[$id,$amount,$status,$reason===''?'Đã thu tiền đơn xe '.$r['code']:$reason,$fingerprint]);if($status==='PAID'){$this->credit($s,$id);$this->query("UPDATE jingo_ride_payment_attempts SET status='PAID' WHERE id=?",[$a['id']]);}if($r)$this->query('INSERT INTO jingo_ride_payment_events(event_id,ride_id) VALUES (?,?)',[$id,$r['id']]);return ['success'=>true];
    }
}
